public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Basic validation
    if (n <= 0 || start == null || end == null || start.length != n || end.length != n) {
        throw new IllegalArgumentException("Invalid input parameters.");
    }
    if (paths == null) {
        return start.length == 0 && end.length == 0 ? "can be travelled" : "cannot be travelled";
    }

    // Helper to convert coordinate array to a string key
    java.util.function.Function<int[], String> coordKey = coord -> {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            if (i > 0) sb.append(",");
            sb.append(coord[i]);
        }
        return sb.toString();
    };

    // Build adjacency list
    java.util.Map<String, java.util.List<int[]>> graph = new java.util.HashMap<>();
    for (int[] path : paths) {
        if (path == null || path.length != 2 * n) {
            continue; // skip malformed path
        }
        int[] a = new int[n];
        int[] b = new int[n];
        System.arraycopy(path, 0, a, 0, n);
        System.arraycopy(path, n, b, 0, n);
        String keyA = coordKey.apply(a);
        String keyB = coordKey.apply(b);
        graph.computeIfAbsent(keyA, k -> new java.util.ArrayList<>()).add(b);
        graph.computeIfAbsent(keyB, k -> new java.util.ArrayList<>()).add(a);
    }

    String startKey = coordKey.apply(start);
    String endKey = coordKey.apply(end);

    // If start and end are same
    if (startKey.equals(endKey)) {
        return "can be travelled";
    }

    // BFS
    java.util.Queue<String> queue = new java.util.LinkedList<>();
    java.util.Set<String> visited = new java.util.HashSet<>();
    queue.offer(startKey);
    visited.add(startKey);

    while (!queue.isEmpty()) {
        String currentKey = queue.poll();
        java.util.List<int[]> neighbors = graph.get(currentKey);
        if (neighbors == null) continue;
        for (int[] neighbor : neighbors) {
            String neighborKey = coordKey.apply(neighbor);
            if (neighborKey.equals(endKey)) {
                return "can be travelled";
            }
            if (visited.add(neighborKey)) {
                queue.offer(neighborKey);
            }
        }
    }

    return "cannot be travelled";
}

public static String convertDatesToWeekdays(String date) {
    try {
        if (date == null) {
            return "Invalid input";
        }
        String[] parts = date.trim().split("\\s+");
        if (parts.length != 3) {
            return "Invalid input";
        }
        int month = Integer.parseInt(parts[0]);
        int day = Integer.parseInt(parts[1]);
        int year = Integer.parseInt(parts[2]);

        java.time.LocalDate localDate = java.time.LocalDate.of(year, month, day);

        java.time.format.DateTimeFormatter monthFormatter =
                java.time.format.DateTimeFormatter.ofPattern("MMMM", java.util.Locale.ENGLISH);
        java.time.format.DateTimeFormatter weekdayFormatter =
                java.time.format.DateTimeFormatter.ofPattern("EEEE", java.util.Locale.ENGLISH);

        String monthName = localDate.format(monthFormatter);
        String weekday = localDate.format(weekdayFormatter);

        return monthName + " " + day + ", " + year + " is a " + weekday;
    } catch (NumberFormatException | java.time.DateTimeException e) {
        return "Invalid input";
    }
}

