    java.util.Map<Integer, Integer> freq = new java.util.HashMap<>();
    for (int val : arr) {
        int r = ((val % k) + k) % k;
        freq.put(r, freq.getOrDefault(r, 0) + 1);
    }

    // Check pairing conditions
    for (java.util.Map.Entry<Integer, Integer> entry : freq.entrySet()) {
        int rem = entry.getKey();
        int count = entry.getValue();
        int complement = (k - rem) % k;

        // Special cases: remainder 0 or (k even && remainder k/2) must appear an even number of times
        if (rem == 0 || (k % 2 == 0 && rem == k / 2)) {
            if ((count & 1) != 0) {
                return false;
            }
        } else {
            // For other remainders, counts must match with their complement
            int compCount = freq.getOrDefault(complement, 0);
            if (compCount != count) {
                return false;
            }
        }
    }

    return true;
}

