public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n < 2) return false;
    int totalSum = 0;
    for (int num : nums) totalSum += num;

    // dp[k] holds all subset sums achievable with k elements
    java.util.ArrayList<java.util.Set<Integer>> dp = new java.util.ArrayList<>(n + 1);
    for (int i = 0; i <= n; i++) {
        dp.add(new java.util.HashSet<Integer>());
    }
    dp.get(0).add(0);

    for (int num : nums) {
        for (int k = n - 1; k >= 0; k--) {
            java.util.Set<Integer> currentSet = dp.get(k);
            java.util.Set<Integer> nextSet = dp.get(k + 1);
            for (int sum : currentSet) {
                nextSet.add(sum + num);
            }
        }
    }

    for (int k = 1; k <= n / 2; k++) {
        if ((totalSum * k) % n != 0) continue;
        int target = (totalSum * k) / n;
        if (dp.get(k).contains(target)) return true;
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null) {
        throw new IllegalArgumentException("Input array cannot be null");
    }
    int n = cost.length;
    if (n == 0) {
        return 0;
    }

    // dp[0] and dp[1] are the minimal costs to reach step 0 and step 1
    int prev = 0; // cost to reach step 0
    int curr = 0; // cost to reach step 1

    for (int i = 0; i < n; i++) {
        int next = Math.min(prev, curr) + cost[i];
        prev = curr;
        curr = next;
    }

    // After the loop, curr is the cost to reach the top (step n),
    // and prev is the cost to reach step n-1.
    return Math.min(prev, curr);
}

