public boolean hasAllCodes(String s, int k) {
    // Validate input
    if (s == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }
    if (k < 0) {
        throw new IllegalArgumentException("k must be non‑negative");
    }
    // Edge cases
    if (k == 0) {
        // Only the empty string is required
        return true;
    }
    if (s.length() < k) {
        return false;
    }
    // Number of distinct binary strings of length k
    long totalCodes = 1L << k;
    // If totalCodes is too large to materialise in an array, use a HashSet
    java.util.Set<Long> seen;
    if (totalCodes <= Integer.MAX_VALUE) {
        seen = new java.util.HashSet<>((int)totalCodes);
    } else {
        seen = new java.util.HashSet<>();
    }

    long mask = totalCodes - 1;
    long current = 0;
    // Build the first window
    for (int i = 0; i < k; i++) {
        current = (current << 1) | (s.charAt(i) - '0');
    }
    seen.add(current);

    // Slide through the string
    for (int i = 1; i <= s.length() - k; i++) {
        // Shift left by one and mask to keep only k bits
        current = ((current << 1) & mask) | (s.charAt(i + k - 1) - '0');
        seen.add(current);
        // Early exit: if we've already seen all possible codes
        if (seen.size() == totalCodes) {
            return true;
        }
    }
    return seen.size() == totalCodes;
}

