}

public int findMinFibonacciNumbers(int k) {
    // Validate input: k should be positive according to problem statement
    if (k <= 0) {
        throw new IllegalArgumentException("k must be a positive integer");
    }

    // Generate Fibonacci numbers up to k
    int[] fib = new int[45]; // The 45th Fibonacci number exceeds Integer.MAX_VALUE
    fib[0] = 1;
    fib[1] = 1;
    int count = 2;
    while (true) {
        int next = fib[count - 1] + fib[count - 2];
        if (next > k) {
            break;
        }
        fib[count++] = next;
    }

    // Greedy approach: always subtract the largest possible Fibonacci number
    int remaining = k;
    int result = 0;
    for (int i = count - 1; i >= 0 && remaining > 0; i--) {
        int f = fib[i];
        while (remaining >= f) {
            remaining -= f;
            result++;
        }
    }
    return result;
}

public int kthFactor(int n, int k) {
    if (n <= 0 || k <= 0) {
        return -1;
    }
    java.util.List<Integer> small = new java.util.ArrayList<>();
    java.util.List<Integer> large = new java.util.ArrayList<>();
    int limit = (int) Math.sqrt(n);
    for (int i = 1; i <= limit; i++) {
        if (n % i == 0) {
            small.add(i);
            if (i != n / i) {
                large.add(n / i);
            }
        }
    }
    // combine small ascending and large descending
    int total = small.size() + large.size();
    if (k > total) {
        return -1;
    }
    if (k <= small.size()) {
        return small.get(k - 1);
    } else {
        // k-th factor is in the large list, which is in descending order of factors
        int indexInLarge = k - small.size() - 1;
        return large.get(large.size() - 1 - indexInLarge);
    }
}

