    for (int end = idx + 1; end <= s.length(); end++) {
        String part = s.substring(idx, end);
        if (!used.contains(part)) {
            used.add(part);
            dfs(s, end, used, best);
            used.remove(part);
        }
    }
}

public int minOperations(String[] logs) {
    int depth = 0;
    if (logs == null) {
        return 0;
    }
    for (String log : logs) {
        if (log == null) {
            continue;
        }
        String cmd = log.trim();
        if (cmd.equals("./")) {
            // Stay in the current folder; do nothing.
            continue;
        } else if (cmd.equals("../")) {
            // Move up one folder, but cannot go above the root.
            if (depth > 0) {
                depth--;
            }
        } else if (cmd.endsWith("/")) {
            // Enter a new folder.
            depth++;
        }
        // Any other string is treated as malformed and ignored.
    }
    // The current depth represents the number of steps needed to return to root.
    return depth;
}

public String getSmallestString(int n, int k) {
    if (n <= 0 || k < n || k > n * 26) {
        throw new IllegalArgumentException("n must be positive and k must be between n and 26*n");
    }
    char[] result = new char[n];
    // Initialize all characters to 'a'
    for (int i = 0; i < n; i++) {
        result[i] = 'a';
    }
    int remaining = k - n; // total additional value needed beyond all 'a'
    // Increase characters from the end to keep string lexicographically smallest
    for (int i = n - 1; i >= 0 && remaining > 0; i--) {
        int add = Math.min(25, remaining); // maximum we can add to this character
        result[i] = (char) ('a' + add);
        remaining -= add;
    }
    return new String(result);
}

