public static int singleNumber(int[] nums) {
    if (nums == null || nums.length == 0) {
        throw new IllegalArgumentException("Input array must not be null or empty");
    }
    try {
        int[] bitCount = new int[32];
        for (int num : nums) {
            for (int i = 0; i < 32; i++) {
                bitCount[i] += (num >> i) & 1;
            }
        }
        int result = 0;
        for (int i = 0; i < 32; i++) {
            if ((bitCount[i] % 3) != 0) {
                result |= (1 << i);
            }
        }
        return result;
    } catch (Exception e) {
        throw new RuntimeException("Error computing single number", e);
    }
}

public static java.util.List<Integer> findSteppingNumbers(int low, int high) {
    java.util.List<Integer> result = new java.util.ArrayList<>();
    if (low > high) {
        return result;
    }
    java.util.Queue<Long> queue = new java.util.LinkedList<>();

    // Handle zero separately
    if (low <= 0 && 0 <= high) {
        result.add(0);
    }

    // Initialize queue with single digit stepping numbers (1-9)
    for (int i = 1; i <= 9; i++) {
        if (i <= high) {
            queue.offer((long) i);
            if (i >= low) {
                result.add(i);
            }
        }
    }

    while (!queue.isEmpty()) {
        long cur = queue.poll();
        int lastDigit = (int) (cur % 10);

        // Next digit could be lastDigit - 1
        int nextDigit = lastDigit - 1;
        if (nextDigit >= 0) {
            long next = cur * 10 + nextDigit;
            if (next <= high) {
                queue.offer(next);
                if (next >= low) {
                    result.add((int) next);
                }
            }
        }

        // Next digit could be lastDigit + 1
        nextDigit = lastDigit + 1;
        if (nextDigit <= 9) {
            long next = cur * 10 + nextDigit;
            if (next <= high) {
                queue.offer(next);
                if (next >= low) {
                    result.add((int) next);
                }
            }
        }
    }

    java.util.Collections.sort(result);
    return result;
}

public static int countDigitOne(int n) {
    if (n < 0) {
        // Assuming negative input is not valid; return 0 or throw exception as needed
        return 0;
    }
    long nLong = n;
    long factor = 1;
    long count = 0;
    try {
        while (nLong / factor > 0) {
            long lower = nLong % factor;
            long curDigit = (nLong / factor) % 10;
            long higher = nLong / (factor * 10);

            if (curDigit == 0) {
                count += higher * factor;
            } else if (curDigit == 1) {
                count += higher * factor + lower + 1;
            } else {
                count += (higher + 1) * factor;
            }
            factor *= 10;
        }
    } catch (ArithmeticException e) {
        // In case of overflow, return maximum int value as a safe fallback
        return Integer.MAX_VALUE;
    }
    return (int) count;
}

