    }
    int max = 1;
    int count = 1;
    char prev = s.charAt(0);
    for (int i = 1; i < s.length(); i++) {
        char current = s.charAt(i);
        if (current == prev) {
            count++;
        } else {
            if (count > max) {
                max = count;
            }
            count = 1;          // reset for new character
            prev = current;
        }
    }
    // Check the last run
    if (count > max) {
        max = count;
    }
    return max;
}

public static java.util.List<Integer> lexicalOrder(int n) {
    java.util.List<Integer> result = new java.util.ArrayList<>();
    if (n <= 0) {
        return result;
    }
    int cur = 1;
    for (int i = 0; i < n; i++) {
        result.add(cur);
        if (cur * 10 <= n) {
            cur *= 10;
        } else if (cur % 10 != 9 && cur + 1 <= n) {
            cur++;
        } else {
            while ((cur / 10) % 10 == 9 || cur + 1 > n) {
                cur /= 10;
            }
            cur++;
        }
    }
    return result;
}

