public static int minPerfectSquareSum(int n) {
    // Handle invalid input
    if (n < 0) {
        return -1;
    }
    // Base case
    if (n == 0) {
        return 0;
    }

    int[] dp = new int[n + 1];
    // Initialize with a large value
    for (int i = 1; i <= n; i++) {
        dp[i] = Integer.MAX_VALUE;
    }
    dp[0] = 0;

    // Dynamic programming to compute minimal counts
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j * j <= i; j++) {
            int square = j * j;
            int candidate = dp[i - square] + 1;
            if (candidate < dp[i]) {
                dp[i] = candidate;
            }
        }
    }

    return dp[n];
}

